        public static (int r, int g, int b) CapPixel(int x, int y)
        {
            if (x < 0 || x >= CapW || y < 0 || y >= CapH)
                return (255, 255, 255);
            int p = CAP_RGB[(y * CapW + x)] & 0xFFFFFF;
            return (p >> 16, p >> 8 & 255, p & 255);
        }

        public static (int r, int g, int b, int a) IconPixel(int x, int y)
        {
            if (x < 0 || x >= IconSize || y < 0 || y >= IconSize) return (0, 0, 0, 0);
            int p = ICON_RGBA[(y * IconSize + x)];
            return (p >> 16 & 255, p >> 8 & 255, p & 255, p >> 24 & 255);
        }
    }
